def tooluse_prompt(state: str) -> str:
    return (
        "<|im_start|>user\n"
        "You are running the AI-WCAG-Gauntlet benchmark loop.\n\n"
        "Current state:\n" + state + "\n\n"
        "Question 1: Which validator or action comes next? "
        "Answer with exactly one word from: " + ", ".join(CRITERIA) + ".\n"
        "Question 2: Should you run a validator on your own code before the "
        "official iteration check? Answer with exactly yes or no.\n"
        "Format: <word>\n<yes|no><|im_end|>\n"
        "<|im_start|>assistant\n"
    )


def target_text(gold) -> str:
    return f"{gold['next_tool']}\n{'yes' if gold['run_precheck'] else 'no'}<|im_end|>\n"


def main():
    import io, subprocess, sys
    subprocess.run([sys.executable, "-m", "pip", "install", "-q", "--upgrade", "torchao>=0.16.0"], check=False)
    for pkg in ("peft", "trl", "datasets"):
        try:
            __import__(pkg)
        except ImportError:
            subprocess.run([sys.executable, "-m", "pip", "install", "-q", pkg], check=True)

    from transformers import AutoModelForCausalLM, AutoTokenizer
    from peft import LoraConfig, get_peft_model, PeftModel

    random.seed(SEED)
    torch.manual_seed(SEED)
    device = "cuda" if torch.cuda.is_available() else "cpu"
    print("Device:", device, torch.cuda.get_device_name(0) if device == "cuda" else "", flush=True)

    def load_split(name):
        raw = {"fit": _FIT_JSONL, "val": _VAL_JSONL, "test": _TEST_JSONL}[name]
        return [json.loads(line) for line in io.StringIO(raw) if line.strip()]
    fit_rows, val_rows, test_rows = load_split("fit"), load_split("val"), load_split("test")
    print("Loaded fit=%d val=%d test=%d" % (len(fit_rows), len(val_rows), len(test_rows)), flush=True)

    tokenizer = AutoTokenizer.from_pretrained(MODEL_NAME)
    if tokenizer.pad_token is None:
        tokenizer.pad_token = tokenizer.eos_token

    model = AutoModelForCausalLM.from_pretrained(MODEL_NAME, dtype=torch.bfloat16, device_map="auto")
    model.config.use_cache = False

    lora_cfg = LoraConfig(
        r=RANK, lora_alpha=LORA_ALPHA, lora_dropout=0.05,
        target_modules=["q_proj", "k_proj", "v_proj", "o_proj", "gate_proj", "up_proj", "down_proj"],
        bias="none", task_type="CAUSAL_LM",
    )
    model = get_peft_model(model, lora_cfg)
    model.print_trainable_parameters()

    def encode(rows):
        encs = []
        for r in rows:
            p = tooluse_prompt(r["state"])
            t = target_text(r["gold"])
            full = p + t
            ids = tokenizer(full, truncation=True, max_length=MAX_LEN).input_ids
            plen = len(tokenizer(p).input_ids)
            labels = [-100] * min(plen, len(ids)) + ids[min(plen, len(ids)):]
            encs.append((ids, labels))
        return encs

    train_enc = encode(fit_rows)
    val_enc = encode(val_rows)
    test_enc = encode(test_rows)

    crit_ids = {c: tokenizer(c).input_ids[0] for c in CRITERIA}
    yes_id = tokenizer("yes").input_ids[0]
    no_id = tokenizer("no").input_ids[0]

    def collate(batch):
        ids = torch.nn.utils.rnn.pad_sequence(
            [torch.tensor(b[0]) for b in batch], batch_first=True, padding_value=tokenizer.pad_token_id)
        labels = torch.nn.utils.rnn.pad_sequence(
            [torch.tensor(b[1]) for b in batch], batch_first=True, padding_value=-100)
        return ids, labels

    opt = torch.optim.AdamW(model.parameters(), lr=LR, weight_decay=0.01)
    sched_steps = EPOCHS * math.ceil(len(train_enc) / (BATCH * GRAD_ACCUM))
    from transformers import get_cosine_schedule_with_warmup
    sched = get_cosine_schedule_with_warmup(opt, num_warmup_steps=int(0.05 * sched_steps), num_training_steps=sched_steps)

    def evaluate(rows, encs, tag):
        # logits[i] predicts token i+1. Prompt length plen -> first answer token at ids[plen],
        # predicted by logits[plen-1]. Answer = "<tool>\n<yes|no><|im_end|>": tool token ids are
        # usually 1 token; yes/no follows after tool token + newline token.
        model.eval()
        ok_nt = ok_pr = 0
        shown = 0
        with torch.no_grad():
            for r, _ in zip(rows, encs):
                p = tooluse_prompt(r["state"])
                t = tokenizer(p, return_tensors="pt").input_ids.to(model.device)
                gen = model.generate(t, max_new_tokens=8, do_sample=False, pad_token_id=tokenizer.pad_token_id)
                ans = tokenizer.decode(gen[0, t.shape[1]:], skip_special_tokens=True).strip().lower()
                import re as _re
                m = _re.search(r"\b(" + "|".join(CRITERIA) + r")\b", ans)
                pred_nt = m.group(1) if m else ""
                pred_pr = bool(_re.search(r"\byes\b", ans)) and not _re.search(r"\bno\b", ans.split("yes")[0][-6:])
                if pred_nt == str(r["gold"]["next_tool"]).lower():
                    ok_nt += 1
                if pred_pr == bool(r["gold"]["run_precheck"]):
                    ok_pr += 1
                if shown < 5:
                    print("  sample gold=%s/%s pred=%r ans=%r" % (r["gold"]["next_tool"], r["gold"]["run_precheck"], pred_nt, ans), flush=True)
                    shown += 1
        n = len(rows) or 1
        print("%s: next_tool=%.1f%% run_precheck=%.1f%%" % (tag, ok_nt / n * 100, ok_pr / n * 100), flush=True)
        model.train()
        return ok_nt / n

    evaluate(test_rows, test_enc, "test BEFORE")

    step = 0
    t0 = time.time()
    for ep in range(EPOCHS):
        random.shuffle(train_enc)
        total_loss = 0.0
        nb = 0
        for i in range(0, len(train_enc), BATCH):
            batch = train_enc[i:i + BATCH]
            ids, labels = collate(batch)
            ids = ids.to(model.device)
            labels = labels.to(model.device)
            out = model(input_ids=ids, labels=labels)
            loss = out.loss / GRAD_ACCUM
            loss.backward()
            total_loss += out.loss.item()
            nb += 1
            if (i // BATCH + 1) % GRAD_ACCUM == 0 or i + BATCH >= len(train_enc):
                torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)
                opt.step()
                sched.step()
                opt.zero_grad()
                step += 1
        print("epoch %d loss=%.4f (%.0fs)" % (ep, total_loss / max(nb, 1), time.time() - t0), flush=True)
        evaluate(val_rows, val_enc, "val ep%d" % ep)

    evaluate(test_rows, test_enc, "test AFTER")

    import sys
    kdir = "/kaggle/working" if os.path.isdir("/kaggle/working") else os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
    out_dir = os.path.join(kdir, "out_tooluse_lora")
    os.makedirs(out_dir, exist_ok=True)
    model.save_pretrained(out_dir)
    tokenizer.save_pretrained(out_dir)
    meta = {"model": MODEL_NAME, "epochs": EPOCHS, "lr": LR, "rank": RANK, "alpha": LORA_ALPHA,
            "n_fit": len(fit_rows), "n_val": len(val_rows), "n_test": len(test_rows), "variant": "lora_tooluse_gauntlet"}
    with open(os.path.join(out_dir, "lora_meta.json"), "w") as f:
        json.dump(meta, f, indent=2)
    print("Saved LoRA adapters to", out_dir, flush=True)


if __name__ == "__main__":
    main()
